"""Synthetic interface probes, with no engineering reference values."""
import importlib
import inspect
import json
import math
import os
from pathlib import Path
import sys
sys.path.insert(0,str(Path.cwd()/'src'))
results={}

def add(family,label,arguments,expected,call,classify):
    try:
        value=call()
        observed,detail=classify(value)
    except (ValueError,TypeError) as exc:
        observed,detail='reject_with_reason',type(exc).__name__+': '+str(exc)
    except Exception as exc:
        observed,detail='unexpected_error',type(exc).__name__+': '+str(exc)
    results[family]['cases'].append(dict(label=label,arguments=arguments,expected=expected,observed=observed,detail=detail))

def argument(value):
    return 'NaN' if isinstance(value,float) and math.isnan(value) else 'Infinity' if isinstance(value,float) and math.isinf(value) else value

def scalar(value):
    try:finite=math.isfinite(float(value))
    except (ValueError,TypeError):finite=True
    return ('accepted_value' if finite else 'accepted_nonfinite','Value returned without rejection or escalation.')

def returned(value):return 'accepted_value','Input accepted without rejection or escalation.'

modules={
 'asset_integrity':'digitalmodel.asset_integrity.applicability',
 'code_checks':'digitalmodel.code_checks.workflow',
 'riser_fatigue':'digitalmodel.riser_fatigue.workflow',
 'mooring_fatigue':'digitalmodel.mooring_fatigue.workflow',
 'viv_screening':'digitalmodel.viv_screening.inputs',
 'vessel_stability_screening':'digitalmodel.naval_architecture.vessel_stability_screening',
 'hull_girder_screening':'digitalmodel.hull_girder_screening.workflow',
}
for family,module in modules.items():
