            settings={'design_life_years':1.0,'dff':1.0,'sn_curve':{'curve':'F1','environment':'seawater_cp'},'segments':[{'id':label,'outer_diameter_mm':273.1,'wall_thickness_mm':22.2,'wave':{'scf':1.0,'histogram_period_years':1.0,'stress_ranges_MPa':[10.0],'cycles':[cycles]}} for label,cycles in (('first',1.0),('second',2.0))]}
            key=family
        else:
            settings={'design_life_years':1.0,'dff':1.0,'sn_curve':{'curve':'F1','environment':'seawater_cp'},'lines':[{'id':label,'material':'chain','stress_range_bins':[{'stress_range_MPa':10.0,'cycles':cycles}]} for label,cycles in (('first',1.0),('second',2.0))]}
            key=family
        for nonfinite in (False,True):
            current=copy.deepcopy(settings)
            if nonfinite:
                if family=='code_checks':current['inputs']['effective_tension_kN'][1]=math.nan
                elif family=='riser_fatigue':current['segments'][1]['wave']['cycles'][0]=math.nan
                else:current['lines'][1]['stress_range_bins'][0]['cycles']=math.nan
            current['output_dir']=str(Path(os.environ['TMPDIR'])/'aggregate-results'/family/('nan' if nonfinite else 'finite'))
            cfg={key:current}
            def classify(value):
                result=value[key]
                governing=result['governing_result']['arc_length'] if family=='code_checks' else result['governing_segment'] if family=='riser_fatigue' else result['governing_line']
                return ('accepted_nonfinite' if nonfinite else 'select_worst_after_first' if governing in ('second',1.0) else 'wrong_member','Selected member='+str(governing)+'; non-finite case='+str(nonfinite))
            args=json.loads(json.dumps(cfg,allow_nan=True).replace('NaN','"NaN"'))
            args[key]['output_dir']='$TMPDIR/aggregate-results/'+family+('/nan' if nonfinite else '/finite')
            add(family,'nonfinite_member' if nonfinite else 'worst_after_first',args,'reject_with_reason' if nonfinite else 'select_worst_after_first',lambda d=cfg:m.router(d),classify)
    results[family]['solver_module_loaded']=any(name.startswith(('OrcFxAPI','ansys.mapdl','win32com')) for name in sys.modules)
    print(json.dumps({'family':family,'cases_completed':len(results[family]['cases'])}),file=sys.stderr,flush=True)
print(json.dumps(results,indent=2,sort_keys=True,allow_nan=False))
